#include <algorithm>
#include <cstddef>
#include <utility>

class Buffer {
  float* d_ = nullptr;
  std::size_t n_ = 0;
public:
  Buffer() noexcept = default;
  explicit Buffer(std::size_t n) : d_(n ? new float[n]() : nullptr), n_(n) {}
  ~Buffer() { delete[] d_; }

  Buffer(const Buffer& o) : d_(o.n_ ? new float[o.n_] : nullptr), n_(o.n_) {
    std::copy(o.d_, o.d_ + o.n_, d_);
  }
  Buffer(Buffer&& o) noexcept
      : d_(std::exchange(o.d_, nullptr)), n_(std::exchange(o.n_, 0)) {}

  // copy-and-swap: by-value param serves both copy and move assignment.
  // Strong guarantee: if the copy throws, *this is untouched.
  Buffer& operator=(Buffer o) noexcept {
    swap(o);
    return *this;
  }
  void swap(Buffer& o) noexcept {
    std::swap(d_, o.d_);
    std::swap(n_, o.n_);
  }
  friend void swap(Buffer& a, Buffer& b) noexcept { a.swap(b); }

  std::size_t size() const noexcept { return n_; }
  float* data() noexcept { return d_; }
  const float* data() const noexcept { return d_; }
};

