class Buf {
  int* d_; std::size_t cap_, n_ = 0;
public:
  explicit Buf(std::size_t c) : d_(new int[c]), cap_(c) {}
  Buf(Buf&& o) noexcept
    : d_(std::exchange(o.d_, nullptr)),
      cap_(std::exchange(o.cap_, 0)),
      n_(std::exchange(o.n_, 0)) {}
  ~Buf() { delete[] d_; }
  void push(int v) { d_[n_++] = v; }
  std::size_t size() const { return n_; }
  std::size_t capacity() const { return cap_; }
};

int main() {
  Buf a(4);
  a.push(7);
  Buf b = std::move(a);
  std::cout << a.size() << a.capacity() << b.size();
}

Buf& Buf::operator=(Buf&& other) noexcept {
  delete[] d_;
  d_   = std::exchange(other.d_, nullptr);
  cap_ = std::exchange(other.cap_, 0);
  n_   = std::exchange(other.n_, 0);
  return *this;
}

